import {it,expect,vi} from 'vitest'
import {createLivePort} from './live-port'
import {MultiGraph} from './multi-graph'
import {liveFixture,liveTracks} from './live-fixture'
import {RoleGraph} from './role-graph'
import {roleFixture} from './role-fixture'
it('removes audio-thread markers together with a canceled graph',()=>{const p=()=>({value:1,setValueAtTime:vi.fn(),linearRampToValueAtTime:vi.fn(),cancelScheduledValues:vi.fn()}),node=()=>({gain:p(),connect:vi.fn(),disconnect:vi.fn(),start:vi.fn(),stop:vi.fn()}),approval=liveFixture(),buffer:any={duration:80},ready:any={approval,pcm:{a:{drums:buffer,bass:buffer,other:buffer},b:{drums:buffer,bass:buffer,other:buffer,vocals:buffer}}},host:any={ctx:{currentTime:10,sampleRate:44100,createGain:node,createBufferSource:node},cache:{pool:{owners:new Set()}},gate:{},monitor:{port:{postMessage:vi.fn()}},log:vi.fn()},port=createLivePort(host,new URL('https://example.test'),vi.fn()),graph=port.schedule(ready,{gain:{gain:p()}} as any,20);graph.cancel();expect(host.monitor.port.postMessage.mock.calls.at(-1)?.[0]).toEqual({kind:'cancel',planId:approval.id});port.dispose()})
it('commits a native B deck at its approved source offset without restarting playback',()=>{const approval=liveFixture(),{a,b}=liveTracks(approval),old:any={track:a},deck:any={track:b,at:80,offset:60},host:any={ctx:{},cache:{pool:{owners:new Set()}},active:old,tracks:[a,b],position:40,playing:true,busy:false,pending:null,crossGenrePending:null,gate:{locked:true},status:'',log:vi.fn(),cancelPreparation:vi.fn(),graph:vi.fn(),nativeSource:vi.fn(),retire:vi.fn(),protected:vi.fn(),monitor:{port:{postMessage:vi.fn()}}};const port=createLivePort(host,new URL('https://example.test'),vi.fn()),p:any={plan:{id:approval.id,from:a.id,to:b.id,entry:60},source:old,end:80};port.commit(deck,p);expect(host.active).toBe(deck);expect(host.active.offset).toBe(60);expect(host.cancelPreparation).toHaveBeenCalled();expect(host.retire).toHaveBeenCalledWith(old,false);expect(host.log).toHaveBeenCalledWith('handoff_state_commit',expect.objectContaining({transitionFamily:'longmix',bodySourceOffset:60}));port.dispose()})
it('protects A only after its actual muted boundary and never hides an earlier source gap',()=>{const approval=liveFixture(),{a}=liveTracks(approval),stream:any={deadline:19,pins:new Set(['a']),pump:vi.fn(),dispose:vi.fn()},host:any={ctx:{currentTime:10},cache:{pool:{owners:new Set()}},active:null,tracks:[],gate:{},log:vi.fn(),monitor:{},cancelPreparation:vi.fn()},source:any={track:a,stream,sources:[]},port=createLivePort(host,new URL('https://example.test'),vi.fn());const restore=port.detach(source,20);expect(source.stream.deadline).toBe(19);stream.deadline=25;expect(source.stream.deadline).toBe(Infinity);port.silence!(source);expect(stream.dispose).toHaveBeenCalled();expect(source.stream.deadline).toBe(Infinity);restore();expect(source.stream).toBe(stream);port.dispose()})
it('cancels audio-thread markers when an added-source scene is canceled',()=>{const p=()=>({value:1,setValueAtTime:vi.fn(),linearRampToValueAtTime:vi.fn(),cancelScheduledValues:vi.fn()}),node=()=>({gain:p(),connect:vi.fn(),disconnect:vi.fn(),start:vi.fn(),stop:vi.fn()}),approval=liveFixture(),buffer:any={duration:40},ready:any={approval,pcm:{a:{drums:buffer,bass:buffer,other:buffer},b:{drums:buffer,bass:buffer,other:buffer,vocals:buffer}},multi:{approval:{layers:[{source:'c',role:'drums',outputStart:0,loop:true,points:[[0,0],[1,.2],[40,0]]}]},buffers:new Map([['c:drums',buffer]])}},host:any={ctx:{currentTime:10,sampleRate:44100,createGain:node,createBufferSource:node},cache:{pool:{owners:new Set()}},gate:{},monitor:{port:{postMessage:vi.fn()}},log:vi.fn()},port=createLivePort(host,new URL('https://example.test'),vi.fn()),graph=port.schedule(ready,{gain:{gain:p()}}as any,20);expect(graph).toBeInstanceOf(MultiGraph);graph.cancel();expect(host.monitor.port.postMessage.mock.calls.at(-1)?.[0]).toEqual({kind:'cancel',planId:approval.id});port.dispose()})
it('routes strict role replacements through their graph and binds them to the actual prepared AB',()=>{
 const p=()=>({value:1,setValueAtTime:vi.fn(),linearRampToValueAtTime:vi.fn(),cancelScheduledValues:vi.fn()}),node=()=>({gain:p(),connect:vi.fn(),disconnect:vi.fn(),start:vi.fn(),stop:vi.fn()}),role=roleFixture('roles-cd'),buffer:any={duration:40},ready:any={approval:role.base,pcm:{a:{drums:buffer,bass:buffer,other:buffer},b:{drums:buffer,bass:buffer,other:buffer,vocals:buffer}},roles:{approval:role,buffers:new Map(role.layers.map((l:any)=>[l.source+':'+l.role,{length:Math.round(l.lengthFrames/l.rate),duration:Math.round(l.lengthFrames/l.rate)/44100,numberOfChannels:2,sampleRate:44100}]))}},host:any={ctx:{currentTime:10,sampleRate:44100,createGain:node,createBufferSource:node},cache:{pool:{owners:new Set()}},gate:{},monitor:{port:{postMessage:vi.fn()}},log:vi.fn()},port=createLivePort(host,new URL('https://example.test'),vi.fn())
 const graph=port.schedule(ready,{gain:{gain:p()}}as any,20);expect(graph).toBeInstanceOf(RoleGraph);graph.cancel();expect(host.monitor.port.postMessage.mock.calls.at(-1)?.[0]).toEqual({kind:'cancel',planId:role.base.id})
 ready.approval=structuredClone(role.base);ready.approval.scene.sourceGains.a=1.1;const original=p();expect(()=>port.schedule(ready,{gain:{gain:original}}as any,20)).toThrow(/A.B|原/);expect(original.setValueAtTime).not.toHaveBeenCalled();port.dispose()
})
